oxy_webhelp_navlinks = {"aws_customer_hosted_setup-d39307e16316":{"topics":[{"title":"Set up AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">You can set up an AWS cloud account in <span class=\"ph\">RSC<\/span> and start protecting your         AWS workloads.<\/p>","href":"saas\/aws_cloud_acc_setup.html","attributes":{"data-id":"aws_cloud_acc_setup"},"menu":{"hasChildren":false},"tocID":"aws_cloud_acc_setup-d39307e16330","next":"aws_cloud_acc_setup-d39307e16330"},{"title":"Set up Exocompute on AWS","shortdesc":"<p class=\"shortdesc\">With the Exocompute on AWS feature, <span class=\"ph\">RSC<\/span> launches an Elastic         Kubernetes Service cluster to perform various operations to protect AWS workloads. <span class=\"ph\">RSC<\/span> uses the Elastic Kubernetes Service cluster as a compute resource in         your AWS account.<\/p>","href":"saas\/exocompute_for_aws.html","attributes":{"data-id":"exocompute_for_aws"},"menu":{"hasChildren":false},"tocID":"exocompute_for_aws-d39307e16840","next":"exocompute_for_aws-d39307e16840"},{"title":"Set up AWS storage tiering","shortdesc":"<p class=\"shortdesc\">You can use AWS storage tiering to archive Amazon EC2 instance<span class=\"ph\">, EBS volume, or DynamoDB table<\/span> snapshots         that exceed a specified threshold to Amazon S3 storage classes. By archiving snapshots to         these storage classes, you can optimize costs.<\/p>","href":"saas\/aws_storage_tiering_setup.html","attributes":{"data-id":"aws_storage_tiering_setup"},"menu":{"hasChildren":false},"tocID":"aws_storage_tiering_setup-d39307e17452","next":"aws_storage_tiering_setup-d39307e17452"}]}};